B.agU=new A.ya("Kort info f\xf6r dig som jobbar med VMB",B.b9x,"Faktura skickad",null)
B.ah2=new A.pc("Molnsynk","Med Pro-paketet kan du dela kunder, offerter och fakturor mellan upp till tre enheter.")
